```ts
// profileCache.ts
import { fetchProfile, type Profile } from "./profileApi"; // your existing loader

const TTL_MS = 60_000;
const MAX_ENTRIES = 10_000;

type Entry = { value: Promise<Profile>; expires: number };
const cache = new Map<string, Entry>();

export function getProfile(userId: string): Promise<Profile> {
  const hit = cache.get(userId);
  if (hit && hit.expires > Date.now()) return hit.value;

  // Cache the promise, not the result: concurrent misses share one fetch.
  const value = fetchProfile(userId);
  cache.delete(userId);
  // chisle: evicts oldest-inserted, not LRU; swap for lru-cache if hit rate matters
  if (cache.size >= MAX_ENTRIES) cache.delete(cache.keys().next().value!);
  cache.set(userId, { value, expires: Date.now() + TTL_MS });

  // Don't cache failures.
  value.catch(() => {
    if (cache.get(userId)?.value === value) cache.delete(userId);
  });
  return value;
}

// Call from every profile write path (update, delete, avatar change).
export function invalidateProfile(userId: string): void {
  cache.delete(userId);
}
